package com.bank.jvm;

import java.math.BigDecimal;
import java.util.logging.*;

// A statement-generation workload worth profiling end to end.
public class ProfilingDemo {
    private static final Logger log = Logger.getLogger(ProfilingDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        ProfilerLauncher profiler = new ProfilerLauncher();
        profiler.startRecording("/tmp/bank-statements.jfr");

        StatementGenerator generator = new StatementGenerator();
        log.info("Generating end-of-day statements (profiling in progress)...");
        BigDecimal totalFees = generator.generateForAllAccounts(200_000);
        log.info(() -> "Statements generated. Total fees computed: " + totalFees);

        profiler.stopRecording();
        log.info("Open /tmp/bank-statements.jfr in Java Mission Control to analyze hot methods & allocations");
    }
}

