class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}

// ─── Would be in StatementGenerator.java in a real project ───
class StatementGenerator {
    private static final BigDecimal FEE_RATE = new BigDecimal("0.0005");
    // Hot path: builds a statement string and computes a fee per account.
    BigDecimal generateForAllAccounts(int accountCount) {
        BigDecimal totalFees = BigDecimal.ZERO;
        for (int i = 0; i < accountCount; i++) {
            BigDecimal balance = new BigDecimal(100000 + (i % 900000));
            // Deliberately allocation-heavy: string concatenation in a loop.
            String statement = "";
            for (int line = 0; line < 20; line++) {
                statement = statement + "Line " + line + ": balance=" + balance + "\n";
            }
            BigDecimal fee = balance.multiply(FEE_RATE);
            totalFees = totalFees.add(fee);
            if (statement.isEmpty()) totalFees = totalFees.subtract(fee); // keep JIT honest
        }
        return totalFees;
    }
}

