class ProfilerLauncher {
    private static final Logger log = Logger.getLogger(ProfilerLauncher.class.getName());

    // Start a JFR recording using the diagnostic command interface.
    void startRecording(String path) {
        try {
            var dcmd = java.lang.management.ManagementFactory.getPlatformMBeanServer();
            var name = new javax.management.ObjectName("com.sun.management:type=DiagnosticCommand");
            Object[] params = { new String[] {
                    "name=bankProfile", "filename=" + path, "settings=profile" } };
            String[] sig = { String[].class.getName() };
            dcmd.invoke(name, "jfrStart", params, sig);
            log.info("JFR recording started -> " + path);
        } catch (Exception e) {
            log.log(Level.SEVERE, "Could not start JFR (use -XX:StartFlightRecording instead)", e);
        }
    }

    void stopRecording() {
        try {
            var dcmd = java.lang.management.ManagementFactory.getPlatformMBeanServer();
            var name = new javax.management.ObjectName("com.sun.management:type=DiagnosticCommand");
            Object[] params = { new String[] { "name=bankProfile" } };
            String[] sig = { String[].class.getName() };
            dcmd.invoke(name, "jfrStop", params, sig);
            log.info("JFR recording stopped");
        } catch (Exception e) {
            log.log(Level.SEVERE, "Could not stop JFR", e);
        }
    }
}
